-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.stoke_fuel(p_world uuid, c creature, p_room double precision, p_x double precision, p_y double precision)
 RETURNS TABLE(def text, kind text, sid bigint, x integer, y integer, cx double precision, cy double precision)
 LANGUAGE sql
 STABLE
AS $function$
  select (s.it).def, s.kind, s.sid, s.x, s.y, s.cx, s.cy from deed_store_items(p_world, c.keeper) s
   where fuel_value((s.it).def) <= p_room and (s.it).count > 0 and not coalesce((s.it).locked, false)
   order by stoke_rank((s.it).def), (s.cx - p_x) ^ 2 + (s.cy - p_y) ^ 2, s.sid, (s.it).id limit 1
$function$
